import{_ as t,o,c as s,ag as a}from"./chunks/framework.Cyu1VozZ.js";const u=JSON.parse('{"title":"Self-Hosting","description":"","frontmatter":{},"headers":[],"relativePath":"developers/self-hosting.md","filePath":"developers/self-hosting.md"}'),i={name:"developers/self-hosting.md"};function n(d,e,r,c,l,h){return o(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="self-hosting" tabindex="-1">Self-Hosting <a class="header-anchor" href="#self-hosting" aria-label="Permalink to &quot;Self-Hosting&quot;">​</a></h1><p>Wafflebase is open source (Apache-2.0) and designed to run on your own infrastructure. Your data stays on your servers.</p><p>This page covers two different things, and they need different setups:</p><ul><li><strong><a href="#local-development">Running it locally</a></strong> — the dev stack on <code>localhost</code>, which works out of the box.</li><li><strong><a href="#production-deployment">Deploying it somewhere else</a></strong> — which needs the frontend <strong>rebuilt</strong> with your own URLs, a different migration command, and a handful of variables the dev stack defaults for you.</li></ul><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>The frontend&#39;s API and Yorkie addresses are baked in <strong>at build time</strong>, and nothing supplies yours for you. <code>packages/frontend/.env.production</code> is <strong>not</strong> in the repository — it is a deployment&#39;s configuration, and <code>.gitignore</code> ignores it — so a <code>pnpm frontend build</code> with nothing configured falls back to the localhost <code>.env</code> beside it and bakes in <code>http://localhost:3000</code>. That build is visibly broken for anyone not sitting on the machine that made it, which is the intended failure: it points at nothing rather than quietly at somebody else&#39;s service. Supply your own values before you ship; see <a href="#frontend-build-time-configuration">Frontend build-time configuration</a>.</p></div><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>Version</th><th>Where it is pinned</th></tr></thead><tbody><tr><td>Node.js</td><td><strong>22</strong></td><td><code>.nvmrc</code> (<code>22</code>), both <code>Dockerfile</code> stages (<code>node:22-bookworm-slim</code>), and four of the five <code>.github/workflows/ci.yml</code> jobs (<code>node-version: 22.x</code>) — <code>verify-backend-image</code> sets up no Node, because it only builds and runs the container</td></tr><tr><td>pnpm</td><td><strong>10.5.2</strong></td><td>root <code>package.json</code> → <code>&quot;packageManager&quot;: &quot;pnpm@10.5.2&quot;</code>; <code>Dockerfile</code> runs <code>corepack prepare pnpm@10.5.2 --activate</code></td></tr><tr><td>PostgreSQL</td><td><strong>16</strong></td><td><code>docker-compose.yaml</code> and the CI <code>verify-integration</code> service both use <code>postgres:16</code></td></tr><tr><td>Docker Compose</td><td><strong>v2</strong> (<code>docker compose</code>, not <code>docker-compose</code>)</td><td><code>docker-compose.yaml</code> uses <code>profiles:</code> and <code>depends_on: … condition: service_completed_successfully</code></td></tr></tbody></table><p>Notes on these numbers, so you can judge them:</p><ul><li>The root <code>package.json</code> has <strong>no <code>engines</code> field</strong>, so nothing enforces the Node floor at install time. 22 is simply the only version that is built and tested. If you use <a href="https://github.com/nvm-sh/nvm" target="_blank" rel="noreferrer">nvm</a>, <code>nvm use</code> picks it up from <code>.nvmrc</code>.</li><li>pnpm is required, not optional — the repository is a pnpm workspace (<code>pnpm-workspace.yaml</code>) and the lockfile is a pnpm lockfile. <code>corepack enable</code> will honour the pinned version automatically.</li><li><strong>PostgreSQL 16 is what is pinned and tested, not a proven floor.</strong> Nothing in the repository declares a minimum supported major, so an older server may work and is simply untested. Use 16 unless you have a reason not to.</li></ul><h2 id="local-development" tabindex="-1">Local Development <a class="header-anchor" href="#local-development" aria-label="Permalink to &quot;Local Development&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/wafflebase/wafflebase.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wafflebase</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                    # infrastructure</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> backend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                    # dev migrations only</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                                # three dev servers</span></span></code></pre></div><p><code>pnpm dev</code> runs three servers concurrently, not two:</p><table tabindex="0"><thead><tr><th>Server</th><th>Port</th><th>Script</th></tr></thead><tbody><tr><td>Frontend (Vite)</td><td><code>5173</code></td><td><code>pnpm frontend dev</code></td></tr><tr><td>Backend (NestJS, watch mode)</td><td><code>3000</code></td><td><code>pnpm backend start:dev</code></td></tr><tr><td>Documentation (VitePress)</td><td><code>5174</code></td><td><code>pnpm documentation dev</code></td></tr></tbody></table><p>The documentation server is not decorative: <code>packages/frontend/vite.config.ts</code> proxies <code>/docs</code> to <code>http://localhost:5174</code>, so skipping it makes the in-app <strong>Docs</strong> link a dead route in development.</p><p>Open <code>http://localhost:5173</code>.</p><h3 id="what-docker-compose-up-d-starts" tabindex="-1">What <code>docker compose up -d</code> starts <a class="header-anchor" href="#what-docker-compose-up-d-starts" aria-label="Permalink to &quot;What \`docker compose up -d\` starts&quot;">​</a></h3><p>The <strong>default</strong> stack is four services — the compose file gives <code>profiles:</code> only to the analytics services, so everything else starts unconditionally:</p><table tabindex="0"><thead><tr><th>Service</th><th>Image</th><th>Ports</th><th>Purpose</th></tr></thead><tbody><tr><td><code>postgres</code></td><td><code>postgres:16</code></td><td><code>5432</code></td><td>User accounts, document metadata, share links, API keys</td></tr><tr><td><code>yorkie</code></td><td><code>yorkieteam/yorkie:latest</code></td><td><code>8080</code>, <code>8081</code></td><td>CRDT sync (<code>8080</code> RPC, <code>8081</code> profiling — started with <code>--pprof-enabled</code>)</td></tr><tr><td><code>minio</code></td><td><code>minio/minio:RELEASE.2025-09-07T16-13-09Z</code></td><td><code>9000</code>, <code>9001</code></td><td>S3-compatible blob storage (<code>9000</code> API, <code>9001</code> console)</td></tr><tr><td><code>azurite</code></td><td><code>mcr.microsoft.com/azure-storage/azurite:3.35.0</code></td><td><code>10000</code></td><td>Azure Blob emulator, used only by the lakehouse connector-parity test suite</td></tr></tbody></table><p><code>azurite</code> exists for <code>RUN_LAKEHOUSE_INTEGRATION_TESTS</code>; it is inert if you never run those tests. Start a subset if you would rather not run it:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgres</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yorkie</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> minio</span></span></code></pre></div><p>Four more services carry <code>profiles: [&quot;analytics&quot;]</code> and start only with that opt-in profile: <code>kafka</code> and <code>starrocks</code>, plus two one-shot init containers that create the topic and the database schema and then exit. See <a href="#analytics-optional-1">Analytics</a>.</p><h3 id="pnpm-backend-migrate-is-a-development-command" tabindex="-1"><code>pnpm backend migrate</code> is a development command <a class="header-anchor" href="#pnpm-backend-migrate-is-a-development-command" aria-label="Permalink to &quot;\`pnpm backend migrate\` is a development command&quot;">​</a></h3><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;migrate&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;prisma migrate dev --name init&quot;</span></span></code></pre></div><p><code>prisma migrate dev</code> is Prisma&#39;s <strong>development</strong> command: it can generate new migration files from schema drift and can prompt to reset the database. Never point it at production data. The repository itself prescribes the other command for deployments — <code>Dockerfile:86</code> keeps the Prisma CLI in the runtime image so that <em>&quot;init containers can run <code>npx prisma migrate deploy</code>&quot;</em>. See <a href="#running-migrations">Running migrations</a>.</p><h2 id="backend-environment-variables" tabindex="-1">Backend Environment Variables <a class="header-anchor" href="#backend-environment-variables" aria-label="Permalink to &quot;Backend Environment Variables&quot;">​</a></h2><p>Create a <code>.env</code> file in <code>packages/backend/</code>. <code>ConfigModule.forRoot()</code> is called with <code>isGlobal: true</code> and <strong>no <code>validationSchema</code></strong>, so there is no whole-config check at boot and most values are not validated until the feature that reads them runs. A few are still caught at startup, because the provider that needs them reads them in its constructor and Nest instantiates providers eagerly — <code>JWT_SECRET</code> is the notable one: <code>AuthService</code>&#39;s constructor calls <code>requireConfig(&#39;JWT_SECRET&#39;)</code>, which throws <code>JWT_SECRET is required</code> and the process fails to start. Assume nothing else is checked for you.</p><h3 id="required" tabindex="-1">Required <a class="header-anchor" href="#required" aria-label="Permalink to &quot;Required&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>Notes</th></tr></thead><tbody><tr><td><code>DATABASE_URL</code></td><td>Read by <code>prisma/schema.prisma</code> (<code>env(&quot;DATABASE_URL&quot;)</code>)</td></tr><tr><td><code>JWT_SECRET</code></td><td>Signs access tokens and Yorkie auth-webhook tokens <strong>always</strong>, and refresh tokens unless <code>JWT_REFRESH_SECRET</code> is set. Missing, it throws at boot</td></tr><tr><td><code>GITHUB_CLIENT_ID</code></td><td>GitHub OAuth app</td></tr><tr><td><code>GITHUB_CLIENT_SECRET</code></td><td>GitHub OAuth app</td></tr><tr><td><code>GITHUB_CALLBACK_URL</code></td><td>Also the deployment&#39;s declared public scheme — see <a href="#cookies-tls-and-the-callback-url">Cookies, TLS and the callback URL</a></td></tr><tr><td><code>FRONTEND_URL</code></td><td>Where the OAuth callback redirects back to, and the CORS origin</td></tr></tbody></table><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DATABASE_URL=postgresql://wafflebase:wafflebase@localhost:5432/wafflebase</span></span>
<span class="line"><span>JWT_SECRET=your_secret_here</span></span>
<span class="line"><span>GITHUB_CLIENT_ID=your_github_client_id</span></span>
<span class="line"><span>GITHUB_CLIENT_SECRET=your_github_client_secret</span></span>
<span class="line"><span>GITHUB_CALLBACK_URL=http://localhost:3000/auth/github/callback</span></span>
<span class="line"><span>FRONTEND_URL=http://localhost:5173</span></span></code></pre></div><h3 id="server-and-runtime" tabindex="-1">Server and runtime <a class="header-anchor" href="#server-and-runtime" aria-label="Permalink to &quot;Server and runtime&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td><code>PORT</code></td><td><code>3000</code></td><td>The production image also sets <code>ENV PORT=3000</code> and <code>EXPOSE 3000</code></td></tr><tr><td><code>NODE_ENV</code></td><td>unset</td><td><strong>Not just a logging switch.</strong> <code>production</code> empties the MinIO storage fallbacks (<code>file/file.config.ts:8</code>, <code>image/image.config.ts:7</code>) and is the last-resort fallback for cookie <code>Secure</code>. The shipped image sets <code>NODE_ENV=production</code></td></tr><tr><td><code>LOG_LEVEL</code></td><td><code>info</code></td><td>Pino level (<code>app.module.ts</code>)</td></tr><tr><td><code>BACKEND_TRUST_PROXY</code></td><td><code>0</code></td><td>Express <code>trust proxy</code> hop count. <strong>Set to <code>1</code> when you run behind exactly one TLS-terminating proxy</strong> (nginx, Cloudflare) so <code>req.ip</code> is the real client. Leaving it at <code>0</code> behind a proxy makes every request look like it came from the proxy, so the per-IP rate limiter buckets all traffic together; setting it <em>without</em> a real proxy in front lets any client spoof <code>X-Forwarded-For</code> and bypass those limits (<code>main.ts:39</code>)</td></tr><tr><td><code>BACKEND_JSON_BODY_LIMIT</code></td><td><code>25mb</code></td><td>Passed verbatim to <code>body-parser</code>. Raise it if CLI/docx content imports with large inline <code>data:</code> images are rejected</td></tr></tbody></table><h3 id="sessions-and-cookies" tabindex="-1">Sessions and cookies <a class="header-anchor" href="#sessions-and-cookies" aria-label="Permalink to &quot;Sessions and cookies&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td><code>JWT_REFRESH_SECRET</code></td><td>falls back to <code>JWT_SECRET</code></td><td>Set it to an independent value so a leaked access-token secret cannot mint refresh tokens</td></tr><tr><td><code>JWT_ACCESS_EXPIRES_IN</code></td><td><code>1h</code></td><td></td></tr><tr><td><code>JWT_REFRESH_EXPIRES_IN</code></td><td><code>7d</code></td><td></td></tr><tr><td><code>JWT_ACCESS_COOKIE_MAX_AGE_MS</code></td><td><code>3600000</code></td><td>Cookie lifetime; keep it consistent with the token lifetime above</td></tr><tr><td><code>JWT_REFRESH_COOKIE_MAX_AGE_MS</code></td><td><code>604800000</code></td><td></td></tr><tr><td><code>COOKIE_SECURE</code></td><td>derived</td><td><code>true</code>/<code>1</code> or <code>false</code>/<code>0</code> overrides the scheme detection described <a href="#cookies-tls-and-the-callback-url">below</a></td></tr></tbody></table><h3 id="github-enterprise" tabindex="-1">GitHub Enterprise <a class="header-anchor" href="#github-enterprise" aria-label="Permalink to &quot;GitHub Enterprise&quot;">​</a></h3><p>All four are optional; unset, login goes to public github.com. Set <strong>all four</strong> to sign in against a GitHub Enterprise instance (<code>auth/github.strategy.ts</code>):</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GITHUB_AUTHORIZATION_URL=https://ghe.example.com/login/oauth/authorize</span></span>
<span class="line"><span>GITHUB_TOKEN_URL=https://ghe.example.com/login/oauth/access_token</span></span>
<span class="line"><span>GITHUB_USER_PROFILE_URL=https://ghe.example.com/api/v3/user</span></span>
<span class="line"><span>GITHUB_USER_EMAIL_URL=https://ghe.example.com/api/v3/user/emails</span></span></code></pre></div><p><code>GITHUB_USER_EMAIL_URL</code> is separate on purpose: with the <code>user:email</code> scope, <code>passport-github2</code> otherwise fetches emails from <code>api.github.com</code>, where a GHE token fails with <em>&quot;Bad credentials&quot;</em>.</p><h3 id="yorkie" tabindex="-1">Yorkie <a class="header-anchor" href="#yorkie" aria-label="Permalink to &quot;Yorkie&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td><code>YORKIE_RPC_ADDR</code></td><td><code>http://localhost:8080</code></td><td>Backend-side Yorkie address (<code>yorkie/yorkie.service.ts</code>, <code>yorkie/yorkie-admin.service.ts</code>). The <strong>browser</strong> uses <code>VITE_YORKIE_RPC_ADDR</code>, which is a different value on any real deployment</td></tr><tr><td><code>YORKIE_PUBLIC_KEY</code></td><td>unset</td><td>Yorkie project public key used by the backend SDK client</td></tr><tr><td><code>YORKIE_SECRET_KEY</code></td><td>unset</td><td>Project secret key. Enables &quot;currently editing&quot; presence on the documents list, <strong>and</strong> is the HMAC key that verifies the Yorkie event and auth webhooks (<code>document/yorkie-signature.guard.ts</code>). Without it the event webhook is rejected outright</td></tr><tr><td><code>YORKIE_TOKEN_EXPIRES_IN</code></td><td><code>10m</code></td><td>Lifetime of the short-lived token minted by <code>GET /auth/yorkie-token</code> for the auth webhook</td></tr><tr><td><code>YORKIE_AUTH_WEBHOOK_ENFORCE</code></td><td><code>false</code></td><td><code>false</code> = shadow mode (log the decision, allow everything). <code>true</code> = actually deny. See <a href="#yorkie-auth-webhook-per-document-access-control">Yorkie auth webhook</a></td></tr></tbody></table><h3 id="blob-storage-s3-compatible" tabindex="-1">Blob storage (S3-compatible) <a class="header-anchor" href="#blob-storage-s3-compatible" aria-label="Permalink to &quot;Blob storage (S3-compatible)&quot;">​</a></h3><p>Two <strong>separate</strong> buckets with independent settings. Outside production every value falls back to the MinIO container; with <code>NODE_ENV=production</code> every fallback is the empty string, so a misconfigured deployment fails on first use with an explicit S3 error rather than silently authenticating with <code>minioadmin</code>.</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Blob documents: PDFs, image documents, and any other uploaded file</span></span>
<span class="line"><span>FILE_STORAGE_ENDPOINT=http://localhost:9000</span></span>
<span class="line"><span>FILE_STORAGE_BUCKET=wafflebase-files</span></span>
<span class="line"><span>FILE_STORAGE_REGION=us-east-1</span></span>
<span class="line"><span>FILE_STORAGE_ACCESS_KEY=minioadmin</span></span>
<span class="line"><span>FILE_STORAGE_SECRET_KEY=minioadmin</span></span>
<span class="line"><span>FILE_STORAGE_PREFIX=                    # optional object-key prefix</span></span>
<span class="line"><span></span></span>
<span class="line"><span># Images embedded inside documents (sheets, docs, slides, board)</span></span>
<span class="line"><span>IMAGE_STORAGE_ENDPOINT=http://localhost:9000</span></span>
<span class="line"><span>IMAGE_STORAGE_BUCKET=wafflebase-images</span></span>
<span class="line"><span>IMAGE_STORAGE_REGION=us-east-1</span></span>
<span class="line"><span>IMAGE_STORAGE_ACCESS_KEY=minioadmin</span></span>
<span class="line"><span>IMAGE_STORAGE_SECRET_KEY=minioadmin</span></span>
<span class="line"><span>IMAGE_STORAGE_PREFIX=                   # optional object-key prefix</span></span></code></pre></div><p>See <a href="#blob-storage">Blob storage</a> for bucket creation, key prefixes and upload caps.</p><h3 id="datasources-and-lakehouse" tabindex="-1">Datasources and lakehouse <a class="header-anchor" href="#datasources-and-lakehouse" aria-label="Permalink to &quot;Datasources and lakehouse&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td><code>DATASOURCE_ENCRYPTION_KEY</code></td><td>unset</td><td>64 hex characters (32 bytes), AES-256-GCM. <strong>Required on use, not at boot</strong> — see the warning below</td></tr><tr><td><code>LAKEHOUSE_ALLOWED_ENDPOINTS</code></td><td>empty</td><td>Comma-separated <strong>exact</strong> HTTP(S) origins permitted as custom S3 / Azure / GCS-interop endpoints and Iceberg REST catalogs. Empty means none are allowed</td></tr><tr><td><code>LAKEHOUSE_QUERY_TIMEOUT_MS</code></td><td><code>30000</code></td><td>Integer in <code>100</code>–<code>300000</code>. Out of range is clamped to the nearest bound, a non-integer keeps the default; both warn — see the note below</td></tr><tr><td><code>LAKEHOUSE_DUCKDB_MEMORY_LIMIT</code></td><td><code>512MB</code></td><td>Must match <code>^[1-9][0-9]*(KB|MB|GB)$</code>; anything else silently falls back to the default. This one is <strong>not</strong> clamped and logs nothing — it takes a different code path from the four integers</td></tr><tr><td><code>LAKEHOUSE_DUCKDB_THREADS</code></td><td><code>2</code></td><td>Integer in <code>1</code>–<code>32</code>. Clamped, with a warning — see the note below</td></tr><tr><td><code>LAKEHOUSE_DUCKDB_POOL_SIZE</code></td><td><code>2</code></td><td>Integer in <code>1</code>–<code>8</code>. Clamped, with a warning. Operations stay globally serialized regardless, because DuckDB secrets are instance-global</td></tr><tr><td><code>LAKEHOUSE_DUCKDB_MAX_PENDING</code></td><td><code>64</code></td><td>Integer in <code>1</code>–<code>1000</code>. Clamped, with a warning</td></tr><tr><td><code>LAKEHOUSE_DUCKDB_EXTENSION_DIR</code></td><td>unset (<code>~/.duckdb</code>)</td><td>Where DuckDB keeps extension binaries. The production image sets it to <code>/app/.duckdb-extensions</code> and pre-populates it — see <a href="#duckdb-extensions-lakehouse">DuckDB extensions</a></td></tr><tr><td><code>LAKEHOUSE_ALLOW_LOCAL_PATHS</code></td><td><code>false</code></td><td>Trusted-admin feature: lets a lakehouse table point at the server&#39;s own filesystem</td></tr><tr><td><code>LAKEHOUSE_LOCAL_ROOT</code></td><td>unset</td><td>Required when local paths are enabled; paths outside it are rejected</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p><strong>Four of these are clamped, and say so; the memory limit is not.</strong><code>readBoundedInteger()</code> (<code>packages/backend/src/lakehouse/duckdb.service.ts</code>) reads <code>LAKEHOUSE_QUERY_TIMEOUT_MS</code>, <code>LAKEHOUSE_DUCKDB_THREADS</code>, <code>LAKEHOUSE_DUCKDB_POOL_SIZE</code> and <code>LAKEHOUSE_DUCKDB_MAX_PENDING</code>, and it does not treat the two kinds of bad input the same way:</p><ul><li><strong>Out of range</strong> is clamped to the nearest bound, so <code>LAKEHOUSE_DUCKDB_THREADS=64</code> yields <code>32</code> — the maximum, not the default. It warns: <code>LAKEHOUSE_DUCKDB_THREADS=64 is outside the supported range 1-32; using 32.</code></li><li><strong>Not an integer</strong> (<code>abc</code>, <code>2.5</code>, <code>Infinity</code>) keeps the default, because there is no nearest bound for a value that is not a number. It warns: <code>LAKEHOUSE_DUCKDB_THREADS=&quot;abc&quot; is not an integer; using the default 2.</code></li></ul><p>Unset, empty, or whitespace-only is neither of those: it is read as <em>not configured</em>, takes the default, and warns nothing. That is deliberate — <code>Number(&#39;&#39;) === 0</code> would otherwise clamp a bare <code>LAKEHOUSE_DUCKDB_THREADS=</code> down to the minimum.</p><p>Both warnings name the variable, the value read and the value used, and are logged under the <code>DuckDbService</code> context. They are emitted once per setting during startup — these are field initializers on a singleton, so nothing is re-read on the query path. If an effective value does not look like the one you set, the startup log says which substitution happened.</p><p><code>LAKEHOUSE_DUCKDB_MEMORY_LIMIT</code> is the exception. It goes through <code>readMemoryLimit()</code>, which pattern-matches rather than bounds: a value that does not match falls back to <code>512MB</code> silently, with nothing logged. Check that one yourself.</p></div><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p><strong><code>DATASOURCE_ENCRYPTION_KEY</code> is required-on-use, not required-at-boot.</strong><code>datasource/crypto.util.ts</code> reads it inside <code>getKey()</code>, which only runs when a credential is encrypted or decrypted, and <code>app.module.ts</code> passes no <code>validationSchema</code>. A deployment that omits it therefore boots healthy, serves every other feature normally, and returns a 500 the first time somebody creates or opens a datasource or lakehouse connection. Set it if you intend to use those features — and verify it, because a wrong-length value fails the same way (<code>must be a 64-character hex string</code>).</p><p>Generate one with <code>openssl rand -hex 32</code>. It is not rotatable without re-encrypting stored credentials.</p></div><h3 id="miscellaneous" tabindex="-1">Miscellaneous <a class="header-anchor" href="#miscellaneous" aria-label="Permalink to &quot;Miscellaneous&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td><code>WAFFLEBASE_API_ORIGIN</code></td><td>falls back to the origin of <code>GITHUB_CALLBACK_URL</code></td><td>This deployment&#39;s own public API origin. Used to decide whether an absolute image URL stored inside a CRDT document is first-party before re-hosting it across a workspace boundary — the string comes out of the CRDT, where any collaborator could have written <code>https://attacker.example/api/v1/...</code>. <strong>With neither this nor a callback URL set, only root-relative references are re-hosted</strong> — safe, but a no-op on a deployment whose frontend was built with <code>VITE_BACKEND_API_URL</code> (as any non-localhost deployment must be), because those references are then absolute. If you set <code>VITE_BACKEND_API_URL</code>, set this to the same origin</td></tr><tr><td><code>WAFFLEBASE_TEMPLATE_REVIEWER_IDS</code></td><td>empty</td><td>Comma-separated user ids allowed to decide public template-gallery submissions. Empty means nobody, which keeps the public gallery shut. Non-positive-integer entries are dropped, so a typo cannot grant review authority to user <code>0</code></td></tr></tbody></table><h3 id="analytics-optional" tabindex="-1">Analytics (optional) <a class="header-anchor" href="#analytics-optional" aria-label="Permalink to &quot;Analytics (optional)&quot;">​</a></h3><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># WAFFLEBASE_KAFKA_ADDRESSES=localhost:29092</span></span>
<span class="line"><span># WAFFLEBASE_KAFKA_TOPIC=wafflebase-view-events</span></span>
<span class="line"><span># WAFFLEBASE_STARROCKS_DSN=root:@tcp(localhost:9030)/wafflebase</span></span></code></pre></div><p>Leave all three unset to disable analytics entirely. See <a href="#analytics-optional-1">Analytics</a>.</p><h2 id="frontend-build-time-configuration" tabindex="-1">Frontend Build-Time Configuration <a class="header-anchor" href="#frontend-build-time-configuration" aria-label="Permalink to &quot;Frontend Build-Time Configuration&quot;">​</a></h2><p>The frontend is a Vite static build. <code>import.meta.env.VITE_*</code> values are <strong>substituted into the bundle when you build it</strong> — they are not read at runtime, so setting them on the server that serves the files does nothing.</p><p>Exactly <strong>one</strong> env file is committed to the repository, and it is the localhost one:</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># packages/frontend/.env — tracked, deliberately: it is what makes a fresh</span></span>
<span class="line"><span># clone work under \`pnpm dev\` with no configuration at all</span></span>
<span class="line"><span>VITE_FRONTEND_BASENAME=/</span></span>
<span class="line"><span>VITE_BACKEND_API_URL=http://localhost:3000</span></span>
<span class="line"><span>VITE_YORKIE_RPC_ADDR=http://localhost:8080</span></span>
<span class="line"><span>VITE_YORKIE_PUBLIC_KEY=</span></span></code></pre></div><p><code>pnpm frontend build</code> runs <code>vite build</code>, which uses mode <code>production</code>, and Vite loads <code>.env</code>, <code>.env.local</code>, <code>.env.production</code>, <code>.env.production.local</code> in that order with each overriding the ones before it. Only the <strong>first</strong> of those four is in the repository: <code>.env.production</code> is gitignored (root <code>.gitignore</code>) and <code>*.local</code> is too (<code>packages/frontend/.gitignore</code>), because those are a <em>deployment&#39;s</em> configuration rather than the project&#39;s.</p><p>What ships instead is a template, <code>packages/frontend/.env.production.example</code>, documenting each variable. Vite never loads it — <code>.example</code> is not a mode — so copying or otherwise supplying the values is a step you have to take.</p><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p><strong>An unconfigured production build is broken, and that is the design.</strong> With no <code>.env.production</code> and no environment variables, the four localhost values above are what get baked in, so every visitor&#39;s browser calls <code>http://localhost:3000</code> and <code>http://localhost:8080</code> — their own machine, not your server. The page loads and then fails to sign in or sync.</p><p>This replaced a worse failure. A committed <code>.env.production</code> used to carry wafflebase&#39;s own backend, Yorkie project and Google Analytics property, so an unconfigured build worked well enough to deploy while sending your users&#39; traffic to us. If you are building from a checkout older than that change, check <code>packages/frontend/.env.production</code> before you trust the output.</p><p>Verify a build either way: <code>grep -rl api.wafflebase.io packages/frontend/dist</code> must print nothing. Grep for <strong>your backend&#39;s</strong> host to confirm the positive case. Do <em>not</em> grep for <code>api.yorkie.dev</code> — it is the yorkie-js-sdk&#39;s own built-in default <code>rpcAddr</code> and is present in the vendor bundle regardless of how you configured the build, so it is always a false positive.</p></div><p>Three ways to supply the values, best first (note that this is not the precedence order — environment variables outrank every file, including <code>.env.production.local</code>):</p><ol><li><strong><code>packages/frontend/.env.production.local</code></strong> — the highest-precedence file, and gitignored, so your deployment&#39;s URLs never land in a commit. This is the recommended way. Beware <code>.env.local</code>, the intuitive filename: it ranks <strong>below</strong> <code>.env.production</code> and will not override it.</li><li><strong>Environment variables on the build command</strong> — Vite applies any <code>VITE_</code> variable already in <code>process.env</code> after every file, so these beat all four. Best for CI, where nothing is written to disk. This is what wafflebase&#39;s own deploy does; see the &quot;Install and Build&quot; step in <code>.github/workflows/publish-ghpage.yml</code>, which reads them from repository variables and fails the build when the required ones are missing.</li><li><strong>Copying <code>packages/frontend/.env.production.example</code> to <code>.env.production</code></strong> and filling it in — also gitignored, so it will not show up as a repository modification or conflict on an upstream merge.</li></ol><p>Leaving a variable out is not an error and nothing prompts you. Four of the variables in the table below appear in the committed <code>packages/frontend/.env</code> and fall back to whatever it sets, which is <strong>not</strong> the same value in each case:</p><ul><li><code>VITE_BACKEND_API_URL</code> → <code>http://localhost:3000</code></li><li><code>VITE_YORKIE_RPC_ADDR</code> → <code>http://localhost:8080</code></li><li><code>VITE_FRONTEND_BASENAME</code> → <code>/</code></li><li><code>VITE_YORKIE_PUBLIC_KEY</code> → <strong>empty</strong>; the key is declared there with no value, so omitting it builds a client with no <code>apiKey</code>, not one pointed at a local project</li></ul><p>Everything else, <code>VITE_GA_ID</code> included, is genuinely unset because no committed file sets it.</p><table tabindex="0"><thead><tr><th>Variable</th><th>Required for a non-localhost deployment</th><th>Notes</th></tr></thead><tbody><tr><td><code>VITE_BACKEND_API_URL</code></td><td><strong>Yes</strong></td><td>Prefixed onto every backend call (~60 call sites), including the GitHub login link and the notifications SSE stream. Must be the public origin of your backend</td></tr><tr><td><code>VITE_YORKIE_RPC_ADDR</code></td><td><strong>Yes</strong></td><td>Passed to the browser&#39;s Yorkie client (<code>PrivateRoute.tsx</code>, <code>shared-document.tsx</code>, <code>apply-imported-content.ts</code>). This is the address <strong>browsers</strong> reach Yorkie at, which is not the same value as the backend&#39;s <code>YORKIE_RPC_ADDR</code> unless both run on the same host</td></tr><tr><td><code>VITE_YORKIE_PUBLIC_KEY</code></td><td>If your Yorkie project requires it</td><td>The Yorkie project public key, passed as the client <code>apiKey</code></td></tr><tr><td><code>VITE_FRONTEND_BASENAME</code></td><td>Only if not served at <code>/</code></td><td>React Router basename (<code>App.tsx</code>)</td></tr><tr><td><code>VITE_GA_ID</code></td><td><strong>No — leave it unset</strong></td><td>Google Analytics measurement ID. Unset is the correct default and needs no action: no committed file sets it, and <code>gaSnippet()</code> in <code>packages/frontend/vite.config.ts</code> emits no gtag.js when it is missing or empty. Set it only if the property is yours</td></tr><tr><td><code>VITE_DEMO_SHARED_TOKEN</code></td><td>No</td><td>Share token backing the sheet demo on the marketing homepage</td></tr><tr><td><code>VITE_DEMO_DOC_SHARED_TOKEN</code></td><td>No</td><td>Same, for the docs demo</td></tr><tr><td><code>VITE_DEMO_SLIDES_SHARED_TOKEN</code></td><td>No</td><td>Same, for the slides demo</td></tr></tbody></table><p>Build with your own values:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">VITE_BACKEND_API_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://api.example.com</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> \\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">VITE_YORKIE_RPC_ADDR=https://yorkie.example.com </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">VITE_YORKIE_PUBLIC_KEY=your_yorkie_public_key </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pnpm </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">frontend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # → packages/frontend/dist</span></span></code></pre></div><p><code>VITE_GA_ID</code> is absent from that list on purpose — unset already means no analytics. Add it only to opt in.</p><p>Or write the same three to <code>packages/frontend/.env.production.local</code>, the last file <code>vite build</code> loads, or to <code>packages/frontend/.env.production</code>. Both are gitignored; <code>.env.production.example</code> is the template for either.</p><p>To ship the in-app documentation alongside the app, use the root script instead — it builds the frontend and VitePress and copies the latter to <code>dist/docs</code>, matching the <code>/docs</code> route the dev server proxies:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:all</span></span></code></pre></div><p>The documentation site is a <strong>second</strong> Vite build with its own configuration, and it reads one variable of its own: <code>packages/documentation/.vitepress/config.ts</code> loads <code>VITE_GA_ID</code> from <code>packages/documentation/</code> and injects gtag.js into every docs page when it is set. That directory&#39;s <code>.env.production</code> is gitignored for the same reason as the frontend&#39;s — it used to be committed carrying wafflebase&#39;s measurement ID, so any <code>pnpm build:all</code> reported into our analytics property — and <code>packages/documentation/.env.production.example</code> is its template. Unset, the docs site emits no analytics either.</p><p>Because a <code>VITE_</code>-prefixed environment variable outranks every <code>.env*</code> file in both builds, one variable on the command covers both:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">VITE_GA_ID</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">G-YOUR-OWN-ID</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:all</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # opt in for app + docs</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build:all</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                             # no analytics anywhere</span></span></code></pre></div><p>Serve <code>packages/frontend/dist</code> from any static host or CDN, with a SPA fallback to <code>index.html</code>.</p><h2 id="github-oauth-setup" tabindex="-1">GitHub OAuth Setup <a class="header-anchor" href="#github-oauth-setup" aria-label="Permalink to &quot;GitHub OAuth Setup&quot;">​</a></h2><ol><li>Go to <a href="https://github.com/settings/developers" target="_blank" rel="noreferrer">GitHub Developer Settings</a>.</li><li>Click <strong>New OAuth App</strong>.</li><li>Set the <strong>Authorization callback URL</strong> to <code>https://your-domain/auth/github/callback</code> — the same value you give <code>GITHUB_CALLBACK_URL</code>.</li><li>Copy the Client ID and Client Secret into <code>packages/backend/.env</code>.</li></ol><h3 id="cookies-tls-and-the-callback-url" tabindex="-1">Cookies, TLS and the callback URL <a class="header-anchor" href="#cookies-tls-and-the-callback-url" aria-label="Permalink to &quot;Cookies, TLS and the callback URL&quot;">​</a></h3><p><code>GITHUB_CALLBACK_URL</code> does double duty: it is where GitHub sends the browser back, and it is how the backend learns <strong>its own public scheme</strong>. That scheme decides whether the login and session cookies carry <code>Secure</code>, and with it the <code>__Host-</code> prefix — the property that stops anything on a sibling subdomain from planting a session or CSRF-state cookie on your origin.</p><p><code>isSecureCookie()</code> (<code>auth/oauth-state.ts</code>) resolves it in this order:</p><ol><li><code>COOKIE_SECURE=true</code>/<code>1</code> → secure. <code>false</code>/<code>0</code> → not secure.</li><li><code>GITHUB_CALLBACK_URL</code> starts with <code>https://</code> → secure; <code>http://</code> → not secure.</li><li>Otherwise (no callback URL configured at all) → <code>NODE_ENV === &#39;production&#39;</code>.</li></ol><p>Three consequences worth knowing before you deploy:</p><ul><li><strong>The shipped Docker image sets <code>NODE_ENV=production</code> while this page&#39;s dev example hands out an <code>http://</code> callback URL.</strong> That combination used to produce <code>Secure</code>/<code>__Host-</code> cookies on a plain-http origin, which browsers discard on arrival — a login that fails because the callback can never find its own state cookie. Reading the callback scheme first is what fixes it, so <strong>the callback URL must be accurate</strong>: it is now the value that decides.</li><li><strong>TLS terminating at a proxy while <code>GITHUB_CALLBACK_URL</code> is still <code>http://</code></strong> reads your https origin as cleartext and drops <code>Secure</code> from the <em>session</em> cookie. Fix it by setting <code>GITHUB_CALLBACK_URL</code> to the https URL your users actually reach; <code>COOKIE_SECURE=true</code> states it directly if you cannot. Running <code>NODE_ENV=production</code> with a non-loopback <code>http://</code> callback URL logs a warning at the first login for this reason.</li><li><strong><code>wafflebase login</code> (the CLI) refuses a plain-http non-loopback origin.</strong> CLI sign-in answers <code>400 Command-line sign-in requires an https server</code> unless it can see that its consent cookie is trustworthy. <code>cliLoginAvailable()</code> (<code>packages/backend/src/auth/github-auth.guard.ts</code>) allows it when <em>either</em> the cookies are already <code>Secure</code> — an <code>https://</code> callback URL, or <code>COOKIE_SECURE=true</code> — <em>or</em> the callback URL is a loopback one (<code>localhost</code>, <code>127.0.0.1</code>, <code>[::1]</code>, <code>*.localhost</code>). An <code>http://</code> non-loopback callback URL is the case it refuses.</li><li><strong>Leaving <code>GITHUB_CALLBACK_URL</code> unset does not refuse it — under <code>NODE_ENV=production</code> it allows it,</strong> which is the shipped container&#39;s default (<code>Dockerfile</code> sets <code>NODE_ENV=production</code>). With no callback URL and no <code>COOKIE_SECURE</code>, <code>isSecureCookie()</code> (<code>packages/backend/src/auth/oauth-state.ts</code>) falls through to <code>NODE_ENV === &#39;production&#39;</code> and reads the origin as https, so the consent cookie goes out <code>Secure</code> and CLI sign-in is available. That is deliberate rather than an oversight: if the origin turns out to be cleartext the browser discards a <code>Secure</code> <code>__Host-</code> cookie, so the consent gate fails closed and the login cannot complete. The practical consequence is that you cannot infer your deployment&#39;s scheme from whether <code>wafflebase login</code> is offered — set <code>GITHUB_CALLBACK_URL</code> to the https URL your users actually reach and the question does not arise.</li></ul><p>Turning <code>Secure</code> on renames the session cookies (<code>wafflebase_session</code> → <code>__Host-wafflebase_session</code>), and the unprefixed name is deliberately not honoured afterwards. Existing sessions stop being recognised the first time you flip it and users are sent through the login again; logout expires both shapes, so nothing stale is left behind.</p><h2 id="production-deployment" tabindex="-1">Production Deployment <a class="header-anchor" href="#production-deployment" aria-label="Permalink to &quot;Production Deployment&quot;">​</a></h2><h3 id="container-image" tabindex="-1">Container image <a class="header-anchor" href="#container-image" aria-label="Permalink to &quot;Container image&quot;">​</a></h3><p>A production <code>Dockerfile</code> sits at the repository root. It is a two-stage build — stage 1 builds <code>@wafflebase/core</code>, <code>sheets</code>, <code>docs</code>, <code>slides</code> and the backend on the build host; stage 2 installs production dependencies only, generates the Prisma client for the target platform, and copies the built artifacts in.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wafflebase-backend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --env-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> packages/backend/.env</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 3000:3000</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wafflebase-backend</span></span></code></pre></div><p>The image:</p><ul><li>runs <code>node dist/main</code> from <code>/app/packages/backend</code>,</li><li>sets <code>ENV NODE_ENV=production</code> — <strong>which empties the MinIO storage defaults</strong>, so <code>FILE_STORAGE_*</code> and <code>IMAGE_STORAGE_*</code> must be set explicitly or uploads fail on first use,</li><li>sets <code>ENV PORT=3000</code> and <code>EXPOSE 3000</code>,</li><li>sets <code>ENV LAKEHOUSE_DUCKDB_EXTENSION_DIR=/app/.duckdb-extensions</code> and pre-populates it (see <a href="#duckdb-extensions-lakehouse">DuckDB extensions</a>),</li><li>keeps the Prisma CLI available so an init container can run migrations,</li><li>is <strong>glibc-based (<code>node:22-bookworm-slim</code>), not Alpine</strong>, on purpose: DuckDB publishes no <code>delta</code> extension build for <code>linux_arm64_musl</code>.</li></ul><p>The image contains the <strong>backend only</strong>. Build and serve the frontend separately (see <a href="#frontend-build-time-configuration">Frontend build-time configuration</a>), and run PostgreSQL and Yorkie yourself.</p><p>Health endpoints for your orchestrator: <code>GET /health</code> and <code>GET /health/ready</code>.</p><h3 id="running-migrations" tabindex="-1">Running migrations <a class="header-anchor" href="#running-migrations" aria-label="Permalink to &quot;Running migrations&quot;">​</a></h3><p>Use <code>prisma migrate deploy</code> — it applies pending migrations and nothing else.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># From a checkout</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @wafflebase/backend</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prisma</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Or, in the image (an init container / one-shot job)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /app/packages/backend</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prisma@6.6.0</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy</span></span></code></pre></div><p>Do <strong>not</strong> use <code>pnpm backend migrate</code> here — it runs <code>prisma migrate dev</code>, which is interactive, can author new migration files from schema drift, and can offer to reset the database.</p><p>Migrations must complete before the new image serves traffic.</p><h3 id="behind-a-tls-terminating-proxy" tabindex="-1">Behind a TLS-terminating proxy <a class="header-anchor" href="#behind-a-tls-terminating-proxy" aria-label="Permalink to &quot;Behind a TLS-terminating proxy&quot;">​</a></h3><ul><li>Set <code>BACKEND_TRUST_PROXY=1</code> (or your real hop count) so <code>req.ip</code> is the client address rather than the proxy&#39;s. The rate limiter and audit logging key off it.</li><li>Set <code>GITHUB_CALLBACK_URL</code> to the <strong>https</strong> URL users reach, or <code>COOKIE_SECURE=true</code>. See <a href="#cookies-tls-and-the-callback-url">Cookies, TLS and the callback URL</a>.</li><li>Set <code>FRONTEND_URL</code> to the frontend&#39;s public origin (CORS + post-login redirect), and build the frontend with a matching <code>VITE_BACKEND_API_URL</code>.</li><li>Set <code>WAFFLEBASE_API_ORIGIN</code> to the backend&#39;s public origin, since <code>VITE_BACKEND_API_URL</code> makes stored image references absolute.</li></ul><h2 id="yorkie-auth-webhook-per-document-access-control" tabindex="-1">Yorkie Auth Webhook (per-document access control) <a class="header-anchor" href="#yorkie-auth-webhook-per-document-access-control" aria-label="Permalink to &quot;Yorkie Auth Webhook (per-document access control)&quot;">​</a></h2><p>Document content lives in Yorkie, not in this backend — so <strong>until you register the auth webhook, the Yorkie layer enforces no per-document access control at all.</strong> Anyone who can reach your Yorkie server and knows or guesses a document key can attach to it. Registering the webhook is what makes workspace membership and share-link roles apply at the sync layer.</p><p><code>POST /internal/yorkie/auth</code> is HMAC-verified with <code>YORKIE_SECRET_KEY</code> and reads the caller&#39;s identity from a short-lived backend-minted token the frontend supplies via Yorkie&#39;s <code>authTokenInjector</code>. The auth webhook is a <strong>per-project</strong> Yorkie setting, not a server flag:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yorkie</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --rpc-addr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> localhost:8080</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # once, as the project admin</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yorkie</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> project</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> update</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">projec</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --auth-webhook-url</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://api.example.com/internal/yorkie/auth</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --auth-webhook-method-add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> AttachDocument</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --auth-webhook-method-add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PushPull</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --auth-webhook-method-add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Watch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --auth-webhook-method-add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DetachDocument</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --auth-webhook-method-add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Broadcast</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --auth-webhook-method-add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RemoveDocument</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --auth-webhook-method-add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ListRevisions</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --auth-webhook-method-add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> GetRevision</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --auth-webhook-method-add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> RestoreRevision</span></span></code></pre></div><p>Then roll it out:</p><ol><li>Deploy with <code>YORKIE_AUTH_WEBHOOK_ENFORCE=false</code> (<strong>shadow mode</strong>) — the backend computes and logs the decision it <em>would</em> make but allows every request.</li><li>Confirm the logs show no false denials.</li><li>Flip to <code>YORKIE_AUTH_WEBHOOK_ENFORCE=true</code>.</li></ol><p>Unregister with <code>--auth-webhook-method-rm ALL</code> to disable.</p><div class="caution custom-block github-alert"><p class="custom-block-title">CAUTION</p><p><strong>Shadow mode is not protection.</strong> A deployment that registers the methods but leaves <code>YORKIE_AUTH_WEBHOOK_ENFORCE=false</code> allows everything regardless of the computed decision — including an anonymous share-link viewer listing, reading and restoring a document&#39;s full revision history. Both steps are required.</p></div><div class="warning custom-block github-alert"><p class="custom-block-title">WARNING</p><p><strong>Do not register <code>CreateRevision</code>.</strong> Yorkie calls the webhook for it with <code>attributes: null</code> — no document key, no verb — for every caller, and the decision logic fails closed on a document-scoped method with no attributes. Registering it therefore denies <code>CreateRevision</code> to <em>everyone</em>, the document owner included, and &quot;Name current version&quot; stops working. Leaving it unregistered leaves it ungated: any attached client can create a revision. That is a nuisance rather than a destructive hole, and closing it needs an upstream fix.</p></div><p><code>ListRevisions</code> and <code>GetRevision</code> are gated more strictly than their Yorkie verb suggests. Yorkie sends them with verb <code>r</code>, which a share-link <strong>viewer</strong> passes; but a revision snapshot exposes every past state of the document, including content deleted before the link was shared. So the backend requires the same editor-or-member authority a write does for those two. Workspace members and share-link <em>editors</em> keep their history; only viewers lose it. Ordinary reads (<code>PushPull</code>, <code>Watch</code>) are untouched.</p><p>The public template gallery additionally <strong>requires</strong><code>YORKIE_AUTH_WEBHOOK_ENFORCE=true</code>, and refuses to open otherwise: in shadow mode the preview token a public template card hands every visitor would also grant <em>write</em> access to the underlying document.</p><h2 id="blob-storage" tabindex="-1">Blob Storage <a class="header-anchor" href="#blob-storage" aria-label="Permalink to &quot;Blob Storage&quot;">​</a></h2><p>Uploaded files and embedded images are stored as blobs in an S3-compatible object store rather than in Yorkie. They use <strong>two separate buckets</strong> with independent settings:</p><ul><li><strong><code>FILE_STORAGE_*</code></strong> — blob documents: PDFs, image documents, and any other uploaded file (default bucket <code>wafflebase-files</code>).</li><li><strong><code>IMAGE_STORAGE_*</code></strong> — images embedded inside sheets, docs, slides and boards (default bucket <code>wafflebase-images</code>).</li></ul><p>If <code>FILE_STORAGE_*</code> is misconfigured, file upload is unavailable; if <code>IMAGE_STORAGE_*</code> is, image insertion is — in each case the rest of the app runs normally.</p><h3 id="buckets-are-created-on-demand" tabindex="-1">Buckets are created on demand <a class="header-anchor" href="#buckets-are-created-on-demand" aria-label="Permalink to &quot;Buckets are created on demand&quot;">​</a></h3><p>Both services try <code>HeadBucket</code> on startup and fall back to <code>CreateBucket</code> (<code>file/file.service.ts</code>, <code>image/image.service.ts</code>). A failure is logged as a warning and the module boots anyway, so a missing bucket does not stop the server — it surfaces on the first upload.</p><p>Consequently your S3 credentials need <strong>either</strong> <code>s3:CreateBucket</code>, <strong>or</strong> pre-created buckets with <code>HeadBucket</code> permission. Pre-creating them and granting only object-level access is the tighter option.</p><h3 id="key-prefixes" tabindex="-1">Key prefixes <a class="header-anchor" href="#key-prefixes" aria-label="Permalink to &quot;Key prefixes&quot;">​</a></h3><p><code>FILE_STORAGE_PREFIX</code> / <code>IMAGE_STORAGE_PREFIX</code> namespace objects inside a bucket shared with another application; empty (the default) keeps keys at the bucket root. Surrounding <code>/</code> are trimmed. <strong>Treat them as fixed for the deployment&#39;s lifetime</strong> — changing one after uploads orphans every object already stored under the old prefix. The image prefix composes outside the per-workspace key prefix.</p><h3 id="upload-size-caps" tabindex="-1">Upload size caps <a class="header-anchor" href="#upload-size-caps" aria-label="Permalink to &quot;Upload size caps&quot;">​</a></h3><p>There are two upload paths with different caps. They are separate subsystems, not alternatives:</p><table tabindex="0"><thead><tr><th>Path</th><th>Endpoint</th><th>Cap</th><th>Types</th></tr></thead><tbody><tr><td>Blob documents (drag-and-drop onto the documents list; <code>POST /api/v1/.../files</code>)</td><td><code>POST /files</code>, <code>POST /api/v1/workspaces/:wid/files</code></td><td><strong>50 MB</strong>, but <strong>25 MB</strong> when the upload looks like an image</td><td>Any file. The image cap keys off the MIME <strong>and</strong> the extension, so renaming does not evade it</td></tr><tr><td>Images embedded in a document</td><td><code>POST /images</code> (the browser path), <code>POST /api/v1/workspaces/:wid/images</code> (API keys)</td><td><strong>10 MB</strong></td><td><code>image/png</code>, <code>image/jpeg</code>, <code>image/gif</code>, <code>image/webp</code> only</td></tr></tbody></table><p>Both numbers are correct — they belong to two different features, and neither overrides the other.</p><p>The 50 MB figure is also the Multer parsing limit on the blob-document routes, so an oversized body is rejected during parsing rather than buffered whole, and the frontend mirrors the same rule at enqueue time (<code>app/documents/file-meta.ts</code>) so a multi-gigabyte file never crosses the wire at all. On the embedded-image path the frontend downscales an oversized image before uploading rather than refusing it outright, so the 10 MB limit is usually invisible to users.</p><p>The 10 MB is enforced at a different point on each of the two image routes. <code>/api/v1/.../images</code> sets it as a Multer <code>limits.fileSize</code>, so an oversized body is rejected during parsing; the browser&#39;s <code>POST /images</code> uses a bare <code>FileInterceptor</code> with no limit, so the body is buffered whole and <code>ImageService.upload()</code> rejects it afterwards with <code>File too large (max 10 MB)</code>. The cap is the same either way — only the memory an oversized request costs differs.</p><p>Neither cap is configurable by an environment variable; both are compile-time constants. If you front the backend with a proxy, make sure its own body limit is at least 50 MB or it will reject uploads the application would accept.</p><h2 id="analytics-optional-1" tabindex="-1">Analytics (optional) <a class="header-anchor" href="#analytics-optional-1" aria-label="Permalink to &quot;Analytics (optional)&quot;">​</a></h2><p>Wafflebase can record <strong>Share Link view analytics</strong> — views, unique/returning visitors, dwell time, and a per-link breakdown — surfaced on a per-document and per-workspace dashboard. This is entirely optional and <strong>off by default</strong>: with <code>WAFFLEBASE_KAFKA_ADDRESSES</code>, <code>WAFFLEBASE_KAFKA_TOPIC</code> and <code>WAFFLEBASE_STARROCKS_DSN</code> unset, the whole pipeline is a no-op and the dashboard shows &quot;not enabled&quot;. The rest of the app is unaffected.</p><p>The pipeline reuses the same stack Yorkie ships for its own analytics:</p><ul><li><strong>Kafka</strong> — the backend batches client view events (via a <code>sendBeacon</code> endpoint) onto a Kafka topic.</li><li><strong>StarRocks</strong> — a Routine Load ingests the topic into a <code>wafflebase.view_events</code> table; the dashboard queries it back over the MySQL wire protocol.</li></ul><p>Both run as an <strong>opt-in Docker Compose profile</strong> kept out of the default stack:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> analytics</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>That starts <code>kafka</code> (<code>29092</code>), <code>starrocks</code> (<code>8030</code>, <code>9030</code>, <code>8040</code>) and two one-shot init containers that create the topic, database, table and routine load — alongside the default <code>postgres</code> / <code>yorkie</code> / <code>minio</code> / <code>azurite</code> services.</p><p>Then point the backend at them:</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>WAFFLEBASE_KAFKA_ADDRESSES=localhost:29092</span></span>
<span class="line"><span>WAFFLEBASE_KAFKA_TOPIC=wafflebase-view-events</span></span>
<span class="line"><span>WAFFLEBASE_STARROCKS_DSN=root:@tcp(localhost:9030)/wafflebase</span></span></code></pre></div><p>Open a document through a share link to emit events, then visit the workspace <strong>Analytics</strong> tab. Pointing these at brokers that are not running just produces connection errors — leave them commented out until the profile is up.</p><h2 id="duckdb-extensions-lakehouse" tabindex="-1">DuckDB Extensions (lakehouse) <a class="header-anchor" href="#duckdb-extensions-lakehouse" aria-label="Permalink to &quot;DuckDB Extensions (lakehouse)&quot;">​</a></h2><p>The lakehouse connector reads Iceberg and Delta tables from object storage through an embedded DuckDB, which needs four DuckDB extensions — <code>httpfs</code>, <code>iceberg</code>, <code>delta</code>, <code>azure</code> — plus <code>avro</code>, which <code>iceberg</code> pulls in. DuckDB normally downloads these from <code>extensions.duckdb.org</code> on first use.</p><p>The production image downloads them <strong>at build time</strong> into <code>LAKEHOUSE_DUCKDB_EXTENSION_DIR</code> (<code>/app/.duckdb-extensions</code>) for the platform it will run on, so a deployment needs no egress to <code>extensions.duckdb.org</code>. The build step also <code>LOAD</code>s each one, so a platform whose binary is missing fails the build instead of production. Cost: roughly 170 MB of extension binaries, most of it <code>delta</code> (73 MB) and <code>iceberg</code> (44 MB). This is the reason the image is glibc-based — DuckDB publishes no <code>delta</code> build for <code>linux_arm64_musl</code>.</p><p>Outside the image — a developer machine, or an image built without that step — <code>LAKEHOUSE_DUCKDB_EXTENSION_DIR</code> is unset, DuckDB falls back to <code>~/.duckdb</code>, and the service downloads any extension whose <code>LOAD</code> fails. Loading is always tried first, so nothing hits the network once the binaries are present.</p><p>If your network is egress-restricted and you are not using the shipped image, pre-populate an extension directory and point <code>LAKEHOUSE_DUCKDB_EXTENSION_DIR</code> at it, or the app will boot healthy and fail on its first lakehouse read.</p><p>Lakehouse and external-datasource connections also need <code>DATASOURCE_ENCRYPTION_KEY</code> set — see the warning in <a href="#datasources-and-lakehouse">Datasources and lakehouse</a> — and any custom endpoint or Iceberg REST catalog must be listed verbatim in <code>LAKEHOUSE_ALLOWED_ENDPOINTS</code>.</p><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Browser ──── Frontend (static build) ──── Backend (NestJS, :3000)</span></span>
<span class="line"><span>   │                                            │</span></span>
<span class="line"><span>   │                                      ┌─────┴─────┐</span></span>
<span class="line"><span>   └──────── Yorkie server (:8080) ── PostgreSQL   Blob store (S3)</span></span>
<span class="line"><span>                    │                  (metadata)   (files/images)</span></span>
<span class="line"><span>                    └── auth webhook ──► Backend /internal/yorkie/auth</span></span></code></pre></div><ul><li><strong>PostgreSQL</strong> stores user accounts, document metadata, folders, share links, API keys, notifications and template listings.</li><li><strong>Yorkie</strong> handles real-time document synchronization between clients using CRDTs. Browsers talk to it <strong>directly</strong> (<code>VITE_YORKIE_RPC_ADDR</code>), not through the backend — which is why the auth webhook exists.</li><li><strong>Backend</strong> manages authentication, authorization, blob storage, datasources, and the REST API.</li><li><strong>Blob store</strong> holds uploaded files and embedded images.</li><li><strong>Frontend</strong> is a static bundle with its backend and Yorkie addresses compiled in.</li></ul><h2 id="data-ownership" tabindex="-1">Data Ownership <a class="header-anchor" href="#data-ownership" aria-label="Permalink to &quot;Data Ownership&quot;">​</a></h2><p>All your data is stored in:</p><ul><li><strong>PostgreSQL</strong> — user profiles, document records, folders, share links, API keys, notifications, template listings.</li><li><strong>Yorkie</strong> — editable document content (cells, text, slides, notes, board elements, comments) and its revision history.</li><li><strong>Blob storage</strong> — uploaded files, PDFs, image documents and embedded images (S3-compatible).</li></ul><p>You control all of these services, and once the frontend is built with your own values no telemetry leaves your infrastructure. Two notes on that:</p><ul><li><strong>Analytics is opt-in, and unset means off.</strong> <code>VITE_GA_ID</code> is the one third-party hook — it injects gtag.js into the app (<code>vite.config.ts</code>) and into the docs site (<code>.vitepress/config.ts</code>) at build time. No committed file sets it any more, so doing nothing emits no gtag.js and makes no request to Google. You only get analytics by setting it to a property of your own. If you build from a checkout predating that change, or you copied an <code>.env.production</code> from one, check the value — it used to be wafflebase&#39;s measurement ID. See <a href="#frontend-build-time-configuration">Frontend build-time configuration</a>.</li><li>The optional Share Link view-event pipeline records into the Kafka + StarRocks services you run yourself, and only when you enable it.</li></ul><p>Back up your PostgreSQL database, your Yorkie data store, and your blob store to preserve everything. Note that access control over the Yorkie data is only enforced once you have completed <strong>both</strong> steps in <a href="#yorkie-auth-webhook-per-document-access-control">Yorkie auth webhook</a>.</p><h2 id="further-reading" tabindex="-1">Further Reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further Reading&quot;">​</a></h2><ul><li><a href="https://github.com/wafflebase/wafflebase/blob/main/packages/backend/README.md" target="_blank" rel="noreferrer"><code>packages/backend/README.md</code></a> — the authoritative per-variable reference, kept next to the code.</li><li><a href="https://github.com/wafflebase/wafflebase/blob/main/packages/frontend/README.md" target="_blank" rel="noreferrer"><code>packages/frontend/README.md</code></a> — frontend architecture.</li><li><a href="https://github.com/wafflebase/wafflebase/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer"><code>CONTRIBUTING.md</code></a> — development workflow and verification lanes.</li></ul>`,153)])])}const g=t(i,[["render",n]]);export{u as __pageData,g as default};
